-- Milestone 7. Independent resident grants and retained commercial records.
begin;
create table public.portal_memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,customer_id uuid not null,user_id uuid not null references auth.users(id),active boolean not null default true,starts_on date not null,expires_on date check(expires_on>=starts_on),version integer not null default 1,unique(customer_id,user_id),foreign key(organization_id,property_id,customer_id) references public.customers(organization_id,property_id,id));
create table public.communication_preferences(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,customer_id uuid not null unique,language text not null check(language in ('en','es')),in_app boolean not null,email_opt_in boolean not null,sms_opt_in boolean not null,version integer not null default 1,reason text not null check(length(trim(reason)) between 3 and 2000),foreign key(organization_id,property_id,customer_id) references public.customers(organization_id,property_id,id));
create table public.message_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,name text not null check(length(trim(name)) between 1 and 160),language text not null check(language in ('en','es')),category text not null,title text not null check(length(trim(title)) between 1 and 200),body text not null check(length(trim(body)) between 1 and 4000),archived boolean not null default false,version integer not null default 1);
create table public.communications(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,template_id uuid references public.message_templates(id),language text not null check(language in ('en','es')),category text not null,title text not null check(length(trim(title)) between 1 and 200),body text not null check(length(trim(body)) between 1 and 4000),scheduled_for timestamptz,status text not null check(status in ('draft','scheduled','published','cancelled')),published_at timestamptz,decision_reason text not null default '',version integer not null default 1,unique(organization_id,property_id,id));
create table public.communication_recipients(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,communication_id uuid not null,customer_id uuid not null,customer_name text not null,site_label text not null,title text not null check(length(title)<=1000),body text not null check(length(body)<=16000),preference_snapshot jsonb not null,status text not null default 'queued' check(status in ('queued','published','skipped','cancelled')),decision_reason text not null default '',published_at timestamptz,read_at timestamptz,read_by uuid references auth.users(id),unique(communication_id,customer_id),foreign key(organization_id,property_id,communication_id) references public.communications(organization_id,property_id,id),foreign key(organization_id,property_id,customer_id) references public.customers(organization_id,property_id,id));
create table public.communication_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,communication_id uuid not null,body text not null check(length(trim(body)) between 3 and 2000),foreign key(organization_id,property_id,communication_id) references public.communications(organization_id,property_id,id));
create table public.portal_contact_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,customer_id uuid not null,membership_id uuid not null references public.portal_memberships(id),proposed jsonb not null check(jsonb_typeof(proposed)='object'),customer_updated_at timestamptz not null,status text not null default 'pending' check(status in ('pending','approved','declined','cancelled')),decision_reason text not null default '',version integer not null default 1,foreign key(organization_id,property_id,customer_id) references public.customers(organization_id,property_id,id));
create table public.portal_maintenance_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null,property_id uuid not null,customer_id uuid not null,membership_id uuid not null references public.portal_memberships(id),work_order_id uuid not null unique,request_snapshot jsonb not null check(jsonb_typeof(request_snapshot)='object'),foreign key(organization_id,property_id,customer_id) references public.customers(organization_id,property_id,id),foreign key(organization_id,property_id,work_order_id) references public.work_orders(organization_id,property_id,id));
create table public.account_exports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),status text not null default 'pending' check(status in ('pending','ready','failed')),sha256 text check(sha256~'^[a-f0-9]{64}$'),byte_size bigint check(byte_size between 1 and 20971520),manifest jsonb,reason text not null check(length(trim(reason)) between 3 and 2000),failure_code text not null default '');
create table private.commercial_requests(id uuid primary key,actor_id uuid not null references auth.users(id),command text not null,payload jsonb not null,result jsonb not null);
create table private.commercial_limits(actor_id uuid not null references auth.users(id),action text not null,window_started timestamptz not null,used integer not null,primary key(actor_id,action));
do $$declare t text;begin
 foreach t in array array['portal_memberships','communication_preferences','message_templates','communications','communication_recipients','communication_notes','portal_contact_requests','portal_maintenance_requests','account_exports'] loop
  execute format('alter table public.%I add created_by uuid not null references auth.users(id),add updated_by uuid not null references auth.users(id),add created_at timestamptz not null default now(),add updated_at timestamptz not null default now()',t);
  if t<>'account_exports' then execute format('alter table public.%I add foreign key(organization_id,property_id) references public.properties(organization_id,id)',t);execute format('create index on public.%I(organization_id,property_id)',t);end if;
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);
  execute format('create trigger a_stamp before insert or update on public.%I for each row execute function private.stamp_record()',t);execute format('create trigger z_audit after insert or update on public.%I for each row execute function private.write_audit()',t);
  if t='portal_memberships' then execute 'create policy owner_read on public.portal_memberships for select to authenticated using(private.org_role(organization_id,array[''owner'',''admin'']))';
  elsif t='account_exports' then execute 'create policy owner_read on public.account_exports for select to authenticated using(private.org_role(organization_id,array[''owner'']))';
  else execute format('create policy office_read on public.%I for select to authenticated using(private.operations_manager(organization_id,property_id))',t);end if;
 end loop;
 foreach t in array array['commercial_requests','commercial_limits'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);end loop;
end $$;
create index portal_user_idx on public.portal_memberships(user_id,active,starts_on,expires_on);
create index recipient_customer_idx on public.communication_recipients(customer_id,status,created_at desc,id desc);
create index messages_schedule_idx on public.communications(property_id,status,scheduled_for);
create unique index contact_pending_idx on public.portal_contact_requests(customer_id,created_by) where status='pending';
create index contact_customer_idx on public.portal_contact_requests(customer_id,created_at desc,id desc);
create index portal_work_customer_idx on public.portal_maintenance_requests(customer_id,created_at desc,id desc);
create index account_exports_org_idx on public.account_exports(organization_id,created_at desc,id desc);
create function private.portal_customer_access(target uuid,writing boolean default false) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from public.portal_memberships m join public.properties p on p.id=m.property_id join public.customers c on c.id=m.customer_id where m.customer_id=target and m.user_id=(select auth.uid()) and m.active and m.starts_on<=(now() at time zone p.timezone)::date and (m.expires_on is null or m.expires_on>=(now() at time zone p.timezone)::date) and (not writing or(p.archived_at is null and p.operating_status='active' and c.archived_at is null)));
$$;
revoke execute on function private.portal_customer_access(uuid,boolean) from public,anon,authenticated;
create function private.commercial_limit(action_key text,maximum integer,seconds integer) returns void language plpgsql security invoker set search_path='' as $$
declare n integer;begin
 if auth.uid() is null then raise insufficient_privilege;end if;
 insert into private.commercial_limits values(auth.uid(),action_key,now(),1) on conflict(actor_id,action) do update set used=case when commercial_limits.window_started<=now()-make_interval(secs=>seconds) then 1 else commercial_limits.used+1 end,window_started=case when commercial_limits.window_started<=now()-make_interval(secs=>seconds) then now() else commercial_limits.window_started end returning used into n;
 if n>maximum then raise exception 'commercial_rate_limit';end if;
end;$$;
create function private.render_message(source text,context jsonb) returns text language plpgsql immutable set search_path='' as $$
declare rest text=source;result text='';prefix integer;suffix integer;token text;begin
 if source is null or length(trim(source)) not between 1 and 4000 then raise exception 'invalid_message_template';end if;
 loop prefix=strpos(rest,'{{');if prefix=0 then return result||rest;end if;result=result||left(rest,prefix-1);rest=substring(rest from prefix+2);suffix=strpos(rest,'}}');if suffix=0 then raise exception 'invalid_message_template';end if;token=left(rest,suffix-1);if token not in ('customer_name','property_name','site_label','today') then raise exception 'invalid_message_template';end if;result=result||coalesce(context->>token,'');rest=substring(rest from suffix+2);end loop;
end;$$;
create function private.preference_snapshot(target uuid) returns jsonb language sql stable security invoker set search_path='' as $$select coalesce((select jsonb_build_object('version',version,'language',language,'in_app',in_app,'email_opt_in',email_opt_in,'sms_opt_in',sms_opt_in) from public.communication_preferences where customer_id=target),jsonb_build_object('version',null,'language','en','in_app',true,'email_opt_in',false,'sms_opt_in',false));$$;
create function private.set_communication_preferences(org uuid,prop uuid,customer uuid,input jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare existing public.communication_preferences;result_id uuid;begin
 select * into existing from public.communication_preferences where customer_id=customer for update;
 if existing.version is distinct from (input->>'version')::integer then raise exception 'commercial_conflict';end if;
 result_id=coalesce(existing.id,gen_random_uuid());insert into public.communication_preferences(id,organization_id,property_id,customer_id,language,in_app,email_opt_in,sms_opt_in,reason) values(result_id,org,prop,customer,input->>'language',(input->>'in_app')::boolean,(input->>'email_opt_in')::boolean,(input->>'sms_opt_in')::boolean,input->>'reason') on conflict(id) do update set language=excluded.language,in_app=excluded.in_app,email_opt_in=excluded.email_opt_in,sms_opt_in=excluded.sms_opt_in,reason=excluded.reason,version=communication_preferences.version+1;return result_id;
end;$$;
revoke execute on function private.commercial_limit(text,integer,integer),private.render_message(text,jsonb),private.preference_snapshot(uuid),private.set_communication_preferences(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function private.commercial_command(command text,input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare org uuid=(input->>'organization_id')::uuid;prop uuid=nullif(input->>'property_id','')::uuid;op uuid=(input->>'request_id')::uuid;target uuid=nullif(input->>'id','')::uuid;reason text=trim(coalesce(input->>'reason',''));prior private.commercial_requests;result_id uuid;result jsonb;p public.properties;today date;m public.portal_memberships;t public.message_templates;msg public.communications;r public.communication_recipients;c public.customers;pref jsonb;context jsonb;contact public.portal_contact_requests;export public.account_exports;scheduled timestamptz;total integer;
begin
 if auth.uid() is null then raise insufficient_privilege;end if;
 if command in ('begin_export','finish_export') then if not private.org_role(org,array['owner']) then raise insufficient_privilege;end if;perform 1 from public.organizations where id=org for update;
 else
  if not private.operations_manager(org,prop) then raise insufficient_privilege;end if;select * into p from public.properties where id=prop and organization_id=org for update;if p.id is null then raise insufficient_privilege;end if;
  if command<>'set_portal_access' and(p.archived_at is not null or p.operating_status<>'active') then raise exception 'property_unavailable';end if;today=(now() at time zone p.timezone)::date;
 end if;
 if op is null then raise exception 'operation_id_required';end if;
 select * into prior from private.commercial_requests where id=op;if found then if prior.actor_id<>auth.uid() or prior.command<>'staff:'||command or prior.payload<>input then raise exception 'operation_conflict';end if;return prior.result;end if;
 if length(reason) not between 3 and 2000 then raise exception 'commercial_reason_required';end if;
 if command='begin_export' then perform private.commercial_limit('account_export',3,3600);else perform private.commercial_limit('staff_commercial',60,60);end if;
 if command='set_portal_access' then
  if not private.org_role(org,array['owner']) then raise insufficient_privilege;end if;
  select * into c from public.customers where id=(input->>'customer_id')::uuid and property_id=prop and organization_id=org;if c.id is null then raise exception 'commercial_scope';end if;
  if not exists(select 1 from auth.users where id=(input->>'user_id')::uuid) then raise exception 'registered_user_required';end if;
  if target is not null then select * into m from public.portal_memberships where id=target and property_id=prop and organization_id=org for update;if m.id is null then raise insufficient_privilege;end if;if m.version is distinct from(input->>'version')::integer then raise exception 'commercial_conflict';end if;if m.user_id<>(input->>'user_id')::uuid or m.customer_id<>c.id then raise exception 'portal_identity_immutable';end if;end if;
  result_id=coalesce(target,gen_random_uuid());insert into public.portal_memberships(id,organization_id,property_id,customer_id,user_id,active,starts_on,expires_on) values(result_id,org,prop,c.id,(input->>'user_id')::uuid,(input->>'active')::boolean,(input->>'starts_on')::date,nullif(input->>'expires_on','')::date) on conflict(id) do update set active=excluded.active,starts_on=excluded.starts_on,expires_on=excluded.expires_on,version=portal_memberships.version+1;
 elsif command='set_preferences' then
  select * into c from public.customers where id=(input->>'customer_id')::uuid and property_id=prop and organization_id=org;if c.id is null then raise exception 'commercial_scope';end if;result_id=private.set_communication_preferences(org,prop,c.id,input);
 elsif command='save_template' then
  if not private.property_role(org,prop,array['manager']) then raise insufficient_privilege;end if;perform private.render_message(input->>'title','{}');perform private.render_message(input->>'body','{}');
  if target is not null then select * into t from public.message_templates where id=target and organization_id=org and property_id=prop for update;if t.id is null then raise insufficient_privilege;end if;if t.version is distinct from(input->>'version')::integer then raise exception 'commercial_conflict';end if;end if;
  result_id=coalesce(target,gen_random_uuid());insert into public.message_templates(id,organization_id,property_id,name,language,category,title,body,archived) values(result_id,org,prop,input->>'name',input->>'language',input->>'category',input->>'title',input->>'body',(input->>'archived')::boolean) on conflict(id) do update set name=excluded.name,language=excluded.language,category=excluded.category,title=excluded.title,body=excluded.body,archived=excluded.archived,version=message_templates.version+1;
 elsif command='prepare_message' then
  if jsonb_typeof(input->'customer_ids') is distinct from 'array' or jsonb_array_length(input->'customer_ids') not between 1 and 250 then raise exception 'invalid_audience';end if;
  select count(*) into total from public.customers where organization_id=org and property_id=prop and archived_at is null and id in(select value::uuid from jsonb_array_elements_text(input->'customer_ids'));if total<>jsonb_array_length(input->'customer_ids') then raise exception 'invalid_audience';end if;
  if nullif(input->>'template_id','') is not null then select * into t from public.message_templates where id=(input->>'template_id')::uuid and organization_id=org and property_id=prop and not archived;if t.id is null then raise exception 'template_unavailable';end if;if t.version is distinct from(input->>'template_version')::integer then raise exception 'commercial_conflict';end if;end if;
  scheduled=nullif(input->>'scheduled_for','')::timestamptz;if scheduled is not null and(scheduled>now()+interval '366 days' or scheduled<now()-interval '366 days') then raise exception 'invalid_message_schedule';end if;
  insert into public.communications(organization_id,property_id,template_id,language,category,title,body,scheduled_for,status) values(org,prop,t.id,input->>'language',input->>'category',input->>'title',input->>'body',scheduled,case when scheduled is null then 'draft' else 'scheduled' end) returning id into result_id;
  for c in select * from public.customers where organization_id=org and property_id=prop and id in(select value::uuid from jsonb_array_elements_text(input->'customer_ids')) order by id loop
   context=jsonb_build_object('customer_name',trim(c.first_name||' '||c.last_name),'property_name',p.name,'today',today,'site_label',coalesce((select s.label from public.occupancy_stays o join public.sites_units s on s.id=o.site_id where o.customer_id=c.id and o.starts_on<=today and(o.ends_on is null or o.ends_on>today) order by o.starts_on desc,o.id limit 1),''));
   insert into public.communication_recipients(organization_id,property_id,communication_id,customer_id,customer_name,site_label,title,body,preference_snapshot) values(org,prop,result_id,c.id,context->>'customer_name',context->>'site_label',private.render_message(input->>'title',context),private.render_message(input->>'body',context),jsonb_build_object('prepared',private.preference_snapshot(c.id)));
  end loop;
 elsif command in ('publish_message','cancel_message','add_message_note') then
  select * into msg from public.communications where id=target and organization_id=org and property_id=prop for update;if msg.id is null then raise insufficient_privilege;end if;result_id=msg.id;
  if command='add_message_note' then insert into public.communication_notes(organization_id,property_id,communication_id,body) values(org,prop,msg.id,reason) returning id into result_id;
  else
   if msg.version is distinct from(input->>'version')::integer then raise exception 'commercial_conflict';end if;if msg.status not in ('draft','scheduled') then raise exception 'invalid_message_transition';end if;
   if command='publish_message' then
    if msg.scheduled_for>now() then raise exception 'message_not_due';end if;
    for r in select * from public.communication_recipients where communication_id=msg.id order by id for update loop
     pref=private.preference_snapshot(r.customer_id);update public.communication_recipients set status=case when exists(select 1 from public.customers where id=r.customer_id and archived_at is not null) or not(pref->>'in_app')::boolean or pref->>'language'<>msg.language then 'skipped' else 'published' end,decision_reason=case when exists(select 1 from public.customers where id=r.customer_id and archived_at is not null) then 'customer_archived' when not(pref->>'in_app')::boolean then 'opted_out' when pref->>'language'<>msg.language then 'language_mismatch' else 'available_in_portal' end,preference_snapshot=preference_snapshot||jsonb_build_object('published',pref),published_at=now() where id=r.id;
    end loop;update public.communications set status='published',published_at=now(),decision_reason=reason,version=version+1 where id=msg.id;
   else update public.communications set status='cancelled',decision_reason=reason,version=version+1 where id=msg.id;update public.communication_recipients set status='cancelled',decision_reason=reason where communication_id=msg.id;end if;
  end if;
 elsif command='decide_contact' then
  select * into contact from public.portal_contact_requests where id=target and organization_id=org and property_id=prop for update;if contact.id is null then raise insufficient_privilege;end if;if contact.version is distinct from(input->>'version')::integer then raise exception 'commercial_conflict';end if;if contact.status<>'pending' or input->>'status' not in ('approved','declined') then raise exception 'invalid_contact_transition';end if;
  if input->>'status'='approved' then select * into c from public.customers where id=contact.customer_id for update;if c.archived_at is not null then raise exception 'customer_unavailable';end if;if c.updated_at is distinct from contact.customer_updated_at then raise exception 'contact_source_changed';end if;update public.customers set email=coalesce(contact.proposed->>'email',email),phone=coalesce(contact.proposed->>'phone',phone),mailing_address=coalesce(contact.proposed->>'mailing_address',mailing_address),emergency_contact=coalesce(contact.proposed->>'emergency_contact',emergency_contact),emergency_phone=coalesce(contact.proposed->>'emergency_phone',emergency_phone) where id=c.id;end if;
  update public.portal_contact_requests set status=input->>'status',decision_reason=reason,version=version+1 where id=contact.id;result_id=contact.id;
 elsif command='begin_export' then insert into public.account_exports(organization_id,reason) values(org,reason) returning id into result_id;
 elsif command='finish_export' then
  select * into export from public.account_exports where id=target and organization_id=org and created_by=auth.uid() for update;if export.id is null then raise insufficient_privilege;end if;if export.status<>'pending' or input->>'status' not in ('ready','failed') then raise exception 'invalid_export_transition';end if;
  if input->>'status'='ready' and(coalesce(input->>'sha256','')!~'^[a-f0-9]{64}$' or coalesce((input->>'byte_size')::bigint,0) not between 1 and 20971520 or jsonb_typeof(input->'manifest') is distinct from 'object') then raise exception 'invalid_export_manifest';end if;
  update public.account_exports set status=input->>'status',sha256=nullif(input->>'sha256',''),byte_size=nullif(input->>'byte_size','')::bigint,manifest=input->'manifest',failure_code=left(coalesce(input->>'failure_code',''),80) where id=export.id;result_id=export.id;
 else raise exception 'unknown_commercial_command';end if;
 result=jsonb_build_object('id',result_id);insert into private.commercial_requests values(op,auth.uid(),'staff:'||command,input,result);return result;
end;$$;
create function public.commercial_command(command text,payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.commercial_command(command,payload);$$;
revoke execute on function private.commercial_command(text,jsonb),public.commercial_command(text,jsonb) from public,anon;
grant execute on function private.commercial_command(text,jsonb),public.commercial_command(text,jsonb) to authenticated;
create function private.resident_command(command text,input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare m public.portal_memberships;p public.properties;c public.customers;stay public.occupancy_stays;contact public.portal_contact_requests;prior private.commercial_requests;op uuid=(input->>'request_id')::uuid;target uuid=nullif(input->>'id','')::uuid;reason text=trim(coalesce(input->>'reason',''));today date;result_id uuid;work_id uuid;result jsonb;person uuid;entry record;
begin
 if auth.uid() is null then raise insufficient_privilege;end if;
 select * into m from public.portal_memberships where id=(input->>'membership_id')::uuid and user_id=auth.uid();if m.id is null or not private.portal_customer_access(m.customer_id,command<>'read_message') then raise insufficient_privilege;end if;
 select * into p from public.properties where id=m.property_id and organization_id=m.organization_id for update;
 select * into m from public.portal_memberships where id=m.id and user_id=auth.uid();if not private.portal_customer_access(m.customer_id,command<>'read_message') then raise insufficient_privilege;end if;today=(now() at time zone p.timezone)::date;
 if op is null then raise exception 'operation_id_required';end if;select * into prior from private.commercial_requests where id=op;if found then if prior.actor_id<>auth.uid() or prior.command<>'resident:'||command or prior.payload<>input then raise exception 'operation_conflict';end if;return prior.result;end if;
 if length(reason) not between 3 and 2000 then raise exception 'commercial_reason_required';end if;perform private.commercial_limit('resident_general',60,60);
 if command='set_preferences' then result_id=private.set_communication_preferences(m.organization_id,m.property_id,m.customer_id,input);
 elsif command='read_message' then
  update public.communication_recipients set read_at=coalesce(read_at,now()),read_by=coalesce(read_by,auth.uid()) where id=target and customer_id=m.customer_id and status='published' returning id into result_id;if result_id is null then raise insufficient_privilege;end if;
 elsif command='request_contact' then
  perform private.commercial_limit('resident_contact',3,86400);
  if jsonb_typeof(input->'proposed') is distinct from 'object' or input->'proposed'='{}'::jsonb then raise exception 'invalid_contact_proposal';end if;
  for entry in select * from jsonb_each(input->'proposed') loop
   if entry.key not in ('email','phone','mailing_address','emergency_contact','emergency_phone') or jsonb_typeof(entry.value)<>'string' or length(entry.value#>>'{}')>(case entry.key when 'email' then 320 when 'mailing_address' then 1000 when 'emergency_contact' then 200 else 100 end) then raise exception 'invalid_contact_proposal';end if;
  end loop;
  select * into c from public.customers where id=m.customer_id for update;
  insert into public.portal_contact_requests(organization_id,property_id,customer_id,membership_id,proposed,customer_updated_at) values(m.organization_id,m.property_id,m.customer_id,m.id,input->'proposed',c.updated_at) returning id into result_id;
 elsif command='cancel_contact' then
  select * into contact from public.portal_contact_requests where id=target and customer_id=m.customer_id and created_by=auth.uid() for update;if contact.id is null then raise insufficient_privilege;end if;if contact.version is distinct from(input->>'version')::integer or contact.status<>'pending' then raise exception 'commercial_conflict';end if;update public.portal_contact_requests set status='cancelled',decision_reason=reason,version=version+1 where id=contact.id;result_id=contact.id;
 elsif command='new_maintenance' then
  perform private.commercial_limit('resident_maintenance',5,3600);
  select * into stay from public.occupancy_stays where customer_id=m.customer_id and property_id=m.property_id and starts_on<=today and(ends_on is null or ends_on>today) and(nullif(input->>'stay_id','') is null or id=(input->>'stay_id')::uuid) order by starts_on desc,id limit 1;
  if stay.id is null then raise exception 'current_stay_required';end if;if input->>'location' not in ('site','common') or input->>'priority' not in ('low','normal','high') then raise exception 'invalid_resident_request';end if;
  insert into public.work_orders(organization_id,property_id,number,title,description,category,priority,site_id,customer_id,requested_on,assigned_to,status,parts_required) values(m.organization_id,m.property_id,private.operations_number(m.property_id,'WO'),input->>'title',input->>'description',input->>'category',input->>'priority',case when input->>'location'='site' then stay.site_id else null end,m.customer_id,today,null,'new','') returning id into work_id;
  insert into public.work_order_events(organization_id,property_id,work_order_id,kind,body,performed_on) values(m.organization_id,m.property_id,work_id,'created','Submitted through the resident portal',today);
  insert into public.portal_maintenance_requests(organization_id,property_id,customer_id,membership_id,work_order_id,request_snapshot) values(m.organization_id,m.property_id,m.customer_id,m.id,work_id,jsonb_build_object('title',input->>'title','description',input->>'description','category',input->>'category','priority',input->>'priority','location',input->>'location','site_label',case when input->>'location'='site' then(select label from public.sites_units where id=stay.site_id) else 'Common area' end)) returning id into result_id;
  for person in select user_id from public.organization_memberships where organization_id=m.organization_id and role in ('owner','admin') union select user_id from public.property_memberships where property_id=m.property_id and organization_id=m.organization_id and role='manager' loop perform private.operations_notice(m.organization_id,m.property_id,person,'Resident maintenance request',input->>'title',work_id,null);end loop;
 else raise exception 'unknown_resident_command';end if;
 result=jsonb_build_object('id',result_id);insert into private.commercial_requests values(op,auth.uid(),'resident:'||command,input,result);return result;
end;$$;
create function public.resident_command(command text,payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.resident_command(command,payload);$$;
create function private.portal_accounts() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'organization_id',m.organization_id,'property_id',m.property_id,'customer_id',m.customer_id,'property_name',p.name,'customer_name',trim(c.first_name||' '||c.last_name),'expires_on',m.expires_on) order by p.name,m.id),'[]'::jsonb) from public.portal_memberships m join public.properties p on p.id=m.property_id join public.customers c on c.id=m.customer_id where auth.uid() is not null and m.user_id=auth.uid() and private.portal_customer_access(m.customer_id,false);
$$;
create function public.portal_accounts() returns jsonb language sql stable security invoker set search_path='' as $$select private.portal_accounts();$$;
-- Preserve only statement evidence. A full source JSON snapshot is never a portal DTO.
create function private.portal_calculation(input jsonb) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('currency',input->'currency','starts_on',input->'starts_on','ends_on',input->'ends_on','due_on',input->'due_on','property',input->'property','customer',input->'customer','site',input->'site','subtotal_cents',input->'subtotal_cents','tax_cents',input->'tax_cents','total_cents',input->'total_cents','rounding',input->'rounding','utilities_reason','','rent_reason','','reading_ids','[]'::jsonb,'rate_ids','[]'::jsonb,
 'lines',coalesce((select jsonb_agg(l||jsonb_build_object('source',jsonb_strip_nulls(jsonb_build_object('tax_label',l->'source'->'tax_label','agreed_rate_cents',l->'source'->'agreed_rate_cents','billing_period',l->'source'->'billing_period','starts_on',l->'source'->'starts_on','ends_on',l->'source'->'ends_on','proration',l->'source'->'proration','lease',case when l->'source'->'lease' is not null then jsonb_build_object('id',l->'source'->'lease'->'id') else null end,
 'rate',case when jsonb_typeof(l->'source'->'rate')='object' then(l->'source'->'rate')||jsonb_build_object('reason','','authorization_reference','') else null end,
 'segments',(select jsonb_agg(s||jsonb_build_object('register_event',case when jsonb_typeof(s->'register_event')='object' then(s->'register_event')||jsonb_build_object('reason','Recorded register transition','void_reason','') else null end) order by n) from jsonb_array_elements(coalesce(l->'source'->'segments','[]'::jsonb)) with ordinality x(s,n))))) order by n) from jsonb_array_elements(coalesce(input->'lines','[]'::jsonb)) with ordinality x(l,n)),'[]'::jsonb));
$$;
create function private.portal_collection_account(target uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select account||jsonb_build_object('history',coalesce((select jsonb_agg(e||jsonb_build_object('reason','','reference','')) from jsonb_array_elements(account->'history') e),'[]'::jsonb)) from(select private.collection_account(target) account) x;
$$;
create function private.portal_invoice_statement(target uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('invoice',(to_jsonb(i)-'approved_by'-'created_by'-'updated_by')||jsonb_build_object('approval_reason','','void_reason',''),
 'revision',(to_jsonb(v)-'created_by'-'updated_by')||jsonb_build_object('reason','','total_cents',v.total_cents::text,'calculation',private.portal_calculation(v.calculation)),
 'ledger',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'invoice_id',i.id,'kind',l.kind,'amount_cents',l.amount_cents::text,'created_at',l.created_at,'reason','','reference','') order by l.created_at,l.id) from public.billing_ledger_entries l where l.invoice_id=i.id),'[]'::jsonb),'collection',private.portal_collection_account(i.id))
 from public.invoices i join public.invoice_revisions v on v.id=i.current_revision_id join public.invoice_issues issue on issue.invoice_id=i.id where i.id=target and auth.uid() is not null and private.portal_customer_access(i.customer_id,false);
$$;
create function public.portal_invoice_statement(invoice_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select private.portal_invoice_statement(invoice_id);$$;
create function private.portal_receipt_statement(target uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('receipt',(to_jsonb(r)-'created_by'-'updated_by')||jsonb_build_object('created_by','','snapshot',r.snapshot||jsonb_build_object('source',jsonb_build_object('id',r.source_id),'notes','')),
 'history',case when r.source_kind='payment' then coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'kind',e.kind,'amount_cents',e.amount_cents::text,'effective_on',e.effective_on,'invoice_id',e.invoice_id,'reference','','reason','','reverses_id',e.reverses_id,'created_at',e.created_at) order by e.created_at,e.id) from public.payment_events e where e.payment_id=r.source_id),'[]'::jsonb) else '[]'::jsonb end,
 'available_cents',case when r.source_kind='payment' then private.payment_available(r.source_id)::text else null end,
 'voided',case when r.source_kind='payment' then exists(select 1 from public.payment_events e where e.payment_id=r.source_id and e.kind='void') when r.source_kind='deposit_event' then exists(select 1 from public.deposit_events e where e.reverses_id=r.source_id) else exists(select 1 from public.payment_events e where e.reverses_id=r.source_id) end)
 from public.collection_receipts r where r.id=target and auth.uid() is not null and private.portal_customer_access(r.customer_id,false);
$$;
create function public.portal_receipt_statement(receipt_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select private.portal_receipt_statement(receipt_id);$$;
create function private.portal_snapshot(membership_id uuid,history_page integer default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare m public.portal_memberships;p public.properties;c public.customers;today date;skip integer=history_page*50;invoices jsonb;receipts jsonb;leases jsonb;jobs jsonb;messages jsonb;contacts jsonb;reservations jsonb;begin
 if auth.uid() is null or history_page is null or history_page not between 0 and 10000 then raise insufficient_privilege;end if;select * into m from public.portal_memberships where id=membership_id and user_id=auth.uid();if m.id is null or not private.portal_customer_access(m.customer_id,false) then raise insufficient_privilege;end if;select * into p from public.properties where id=m.property_id;select * into c from public.customers where id=m.customer_id;today=(now() at time zone p.timezone)::date;
 select coalesce(jsonb_agg(row order by row->>'created_at' desc,row->>'id' desc),'[]'::jsonb) into invoices from(select jsonb_build_object('id',i.id,'number',i.number,'starts_on',i.starts_on,'ends_on',i.ends_on,'issued_on',issue.issued_on,'due_on',issue.due_on,'created_at',i.created_at,'total_cents',v.total_cents::text,'account',private.portal_collection_account(i.id)) row from public.invoices i join public.invoice_issues issue on issue.invoice_id=i.id join public.invoice_revisions v on v.id=i.current_revision_id where i.customer_id=c.id order by i.created_at desc,i.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'created_at' desc,row->>'id' desc),'[]'::jsonb) into receipts from(select jsonb_build_object('id',r.id,'number',r.number,'kind',r.snapshot->'kind','amount_cents',r.snapshot->'amount_cents','effective_on',r.snapshot->'effective_on','created_at',r.created_at) row from public.collection_receipts r where r.customer_id=c.id order by r.created_at desc,r.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'starts_on' desc,row->>'id' desc),'[]'::jsonb) into leases from(select jsonb_build_object('id',l.id,'site_label',s.label,'starts_on',l.starts_on,'ends_on',l.ends_on,'billing_period',l.billing_period,'agreed_rate_cents',l.agreed_rate_cents::text,'deposit_required_cents',l.deposit_required_cents::text,'document_reference',l.document_reference,'status',l.status) row from public.lease_terms l join public.sites_units s on s.id=l.site_id where l.customer_id=c.id order by l.starts_on desc,l.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'created_at' desc,row->>'id' desc),'[]'::jsonb) into jobs from(select jsonb_build_object('id',r.id,'work_order_id',w.id,'number',w.number,'title',r.request_snapshot->'title','description',r.request_snapshot->'description','category',r.request_snapshot->'category','priority',r.request_snapshot->'priority','requested_on',w.requested_on,'status',w.status,'completed_on',w.completed_on,'closed_on',w.closed_on,'site_label',r.request_snapshot->'site_label','created_at',r.created_at) row from public.portal_maintenance_requests r join public.work_orders w on w.id=r.work_order_id where r.customer_id=c.id order by r.created_at desc,r.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'published_at' desc,row->>'id' desc),'[]'::jsonb) into messages from(select jsonb_build_object('id',r.id,'title',r.title,'body',r.body,'language',msg.language,'category',msg.category,'published_at',r.published_at,'read_at',r.read_at) row from public.communication_recipients r join public.communications msg on msg.id=r.communication_id where r.customer_id=c.id and r.status='published' order by r.published_at desc,r.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'created_at' desc,row->>'id' desc),'[]'::jsonb) into contacts from(select jsonb_build_object('id',r.id,'proposed',r.proposed,'status',r.status,'decision_reason',r.decision_reason,'version',r.version,'created_at',r.created_at) row from public.portal_contact_requests r where r.customer_id=c.id and r.created_by=auth.uid() order by r.created_at desc,r.id desc limit 51 offset skip) x;
 select coalesce(jsonb_agg(row order by row->>'starts_on' desc,row->>'id' desc),'[]'::jsonb) into reservations from(select jsonb_build_object('id',r.id,'site_label',s.label,'confirmation_code',r.confirmation_code,'starts_on',r.starts_on,'ends_on',r.ends_on,'status',r.status,'billing_period',r.billing_period,'agreed_rate_cents',r.agreed_rate_cents::text) row from public.reservations r join public.sites_units s on s.id=r.site_id where r.customer_id=c.id order by r.starts_on desc,r.id desc limit 51 offset skip) x;
 return jsonb_build_object('membership_id',m.id,'as_of',today,'page',history_page,'read_only',not private.portal_customer_access(c.id,true),
 'property',jsonb_build_object('id',p.id,'name',p.name,'address',p.address,'city',p.city,'state',p.state,'postal_code',p.postal_code,'phone',p.phone,'email',p.email,'timezone',p.timezone),
 'customer',jsonb_build_object('id',c.id,'name',trim(c.first_name||' '||c.last_name),'email',c.email,'phone',c.phone,'mailing_address',c.mailing_address,'emergency_contact',c.emergency_contact,'emergency_phone',c.emergency_phone),'preferences',private.preference_snapshot(c.id),
 'outstanding_cents',coalesce((select sum(private.invoice_outstanding(i.id)) from public.invoices i join public.invoice_issues issue on issue.invoice_id=i.id where i.customer_id=c.id and i.status<>'voided'),0)::text,
 'current_stays',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'site_label',s.label,'starts_on',o.starts_on,'planned_ends_on',o.planned_ends_on,'rate_cents',coalesce(l.agreed_rate_cents,o.agreed_rate_cents)::text,'billing_period',coalesce(l.billing_period,o.billing_period)) order by s.label,o.id) from public.occupancy_stays o join public.sites_units s on s.id=o.site_id left join public.lease_terms l on l.stay_id=o.id and l.status='recorded' and l.starts_on<=today and l.ends_on>today where o.customer_id=c.id and o.starts_on<=today and(o.ends_on is null or o.ends_on>today)),'[]'::jsonb),
 'invoices',coalesce((select jsonb_agg(x) from jsonb_array_elements(invoices) with ordinality e(x,n) where n<=50),'[]'::jsonb),'receipts',coalesce((select jsonb_agg(x) from jsonb_array_elements(receipts) with ordinality e(x,n) where n<=50),'[]'::jsonb),'leases',coalesce((select jsonb_agg(x) from jsonb_array_elements(leases) with ordinality e(x,n) where n<=50),'[]'::jsonb),'requests',coalesce((select jsonb_agg(x) from jsonb_array_elements(jobs) with ordinality e(x,n) where n<=50),'[]'::jsonb),'messages',coalesce((select jsonb_agg(x) from jsonb_array_elements(messages) with ordinality e(x,n) where n<=50),'[]'::jsonb),'contacts',coalesce((select jsonb_agg(x) from jsonb_array_elements(contacts) with ordinality e(x,n) where n<=50),'[]'::jsonb),'reservations',coalesce((select jsonb_agg(x) from jsonb_array_elements(reservations) with ordinality e(x,n) where n<=50),'[]'::jsonb),
 'has_more',jsonb_build_object('invoices',jsonb_array_length(invoices)>50,'receipts',jsonb_array_length(receipts)>50,'leases',jsonb_array_length(leases)>50,'requests',jsonb_array_length(jobs)>50,'messages',jsonb_array_length(messages)>50,'contacts',jsonb_array_length(contacts)>50,'reservations',jsonb_array_length(reservations)>50));
end;$$;
create function public.portal_snapshot(membership_id uuid,history_page integer default 0) returns jsonb language sql stable security invoker set search_path='' as $$select private.portal_snapshot(membership_id,history_page);$$;
revoke execute on function private.portal_calculation(jsonb),private.portal_collection_account(uuid) from public,anon,authenticated;
revoke execute on function private.resident_command(text,jsonb),public.resident_command(text,jsonb),private.portal_accounts(),public.portal_accounts(),private.portal_snapshot(uuid,integer),public.portal_snapshot(uuid,integer),private.portal_invoice_statement(uuid),public.portal_invoice_statement(uuid),private.portal_receipt_statement(uuid),public.portal_receipt_statement(uuid) from public,anon;
grant execute on function private.resident_command(text,jsonb),public.resident_command(text,jsonb),private.portal_accounts(),public.portal_accounts(),private.portal_snapshot(uuid,integer),public.portal_snapshot(uuid,integer),private.portal_invoice_statement(uuid),public.portal_invoice_statement(uuid),private.portal_receipt_statement(uuid),public.portal_receipt_statement(uuid) to authenticated;

commit;
